#!/usr/bin/env python3
"""Compare scan_folder output with an independent, generated byte partition.

Build the example first, then pass its binary. No user folders are scanned.
Only ASCII fixture names are parsed: Rust Debug escaping is not a JSON API.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import random
import subprocess
import tempfile


def digest(path):
    value = hashlib.sha256()
    with path.open("rb") as source:
        for block in iter(lambda: source.read(1024 * 1024), b""):
            value.update(block)
    return value.hexdigest()


def same_bytes(left, right):
    with left.open("rb") as a, right.open("rb") as b:
        while True:
            first, second = a.read(1024 * 1024), b.read(1024 * 1024)
            if first != second:
                return False
            if not first:
                return True


def file_state(path):
    metadata = path.stat()
    return {"sha256": digest(path), "device": metadata.st_dev,
            "inode": metadata.st_ino, "size": metadata.st_size,
            "mtime_ns": metadata.st_mtime_ns, "mode": metadata.st_mode,
            "links": metadata.st_nlink}


def parse_groups(output):
    groups = []
    for line in output.splitlines():
        if line.startswith("Group "):
            groups.append(set())
        elif line.startswith("  "):
            if not groups:
                raise AssertionError("path printed before group")
            path = json.loads(line.strip())
            if path in groups[-1]:
                raise AssertionError("repeated path within group")
            groups[-1].add(path)
        elif line:
            raise AssertionError(f"unexpected output: {line}")
    if any(len(group) < 2 for group in groups):
        raise AssertionError("nonduplicate group")
    partition = {frozenset(group) for group in groups}
    if len(partition) != len(groups):
        raise AssertionError("repeated group")
    return partition


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("binary", type=Path)
    parser.add_argument("--seed", type=int, default=267989)
    parser.add_argument("--report", type=Path)
    parser.add_argument("--large-mib", type=int, default=0,
                        help="optional three-file middle-edit case, 1..256 MiB per file")
    parser.add_argument("--dense-large", action="store_true",
                        help="write every large-file byte instead of creating sparse files")
    args = parser.parse_args()
    if not 0 <= args.large_mib <= 256:
        parser.error("--large-mib must be between 0 and 256")
    if args.dense_large and not args.large_mib:
        parser.error("--dense-large requires a positive --large-mib")
    binary = args.binary.resolve(strict=True)
    binary_hash = digest(binary)
    rng = random.Random(args.seed)
    runs = []
    with tempfile.TemporaryDirectory(prefix="rrrah-folder-oracle-") as temporary:
        root = Path(temporary)
        payloads = [b"", b"\0", bytes(range(256)), b"A" * 131072,
                    b"A" * 131071 + b"B", b"B" + b"A" * 131071]
        payloads += [rng.randbytes(size) for size in
                     (7, 31, 4096, 65535, 65536, 65537, 131073, 262145)]
        expected = {}
        for group, payload in enumerate(payloads):
            for copy in range(1 + group % 5):
                directory = root / f"d{copy % 3}"
                directory.mkdir(exist_ok=True)
                path = directory / f"g{group:02}-c{copy:02}.bin"
                path.write_bytes(payload)
                expected.setdefault(payload, set()).add(str(path))
        for index in range(40):
            path = root / f"unique{index:02}.bin"
            payload = rng.randbytes(4096)
            path.write_bytes(payload)
            expected.setdefault(payload, set()).add(str(path))
        oracle = {frozenset(paths) for paths in expected.values() if len(paths) > 1}
        before = {str(path): file_state(path) for path in root.rglob("*.bin")}
        for name, roots in (("single", [root]),
                            ("overlap", [root, root / "d0", root / "d1"]),
                            ("reversed-overlap", [root / "d1", root / "d0", root])):
            result = subprocess.run([str(binary), *map(str, roots)],
                                    capture_output=True, text=True, timeout=60)
            if result.returncode != 0:
                raise AssertionError(f"{name}: exit {result.returncode}: {result.stderr}")
            if parse_groups(result.stdout) != oracle:
                raise AssertionError(f"{name}: byte partition mismatch")
            runs.append({"case": name, "exit_code": result.returncode,
                         "groups": len(oracle), "stderr": result.stderr})
        after = {str(path): file_state(path) for path in root.rglob("*.bin")}
        if before != after:
            raise AssertionError("fixture content, identity or metadata changed")
        # Exercise the executable's own option terminator, independently of
        # cargo's separator. These names must be scanned, never treated as help.
        for folder_name in ("--help", "-h", "--"):
            directory = root / folder_name
            directory.mkdir()
            payload = b"literal-option-folder\0" + folder_name.encode("ascii")
            for filename in ("first.bin", "second.bin"):
                (directory / filename).write_bytes(payload)
            result = subprocess.run([str(binary), "--", folder_name], cwd=root,
                                    capture_output=True, text=True, timeout=60)
            expected_paths = frozenset(str(Path(folder_name) / filename)
                                       for filename in ("first.bin", "second.bin"))
            if result.returncode != 0 or parse_groups(result.stdout) != {expected_paths}:
                raise AssertionError(f"literal {folder_name}: incorrect scan: {result.stderr}")
            if any(path.read_bytes() != payload for path in directory.iterdir()):
                raise AssertionError(f"literal {folder_name}: fixture content changed")
            runs.append({"case": f"literal-option-folder:{folder_name}",
                         "exit_code": result.returncode, "groups": 1,
                         "stderr": result.stderr})
        empty = root / "empty"
        empty.mkdir()
        missing = root / "missing"
        for name, arguments, expected_exit, stderr_marker in (
                ("empty-folder", [str(empty)], 0, "Scan complete: 0 files observed"),
                ("missing-folder", [str(missing)], 1, "Scan incomplete:"),
                ("no-arguments", [], 2, "Usage:"),
                ("separator-without-folder", ["--"], 2, "Usage:")):
            result = subprocess.run([str(binary), *arguments], cwd=root,
                                    capture_output=True, text=True, timeout=60)
            if (result.returncode != expected_exit or result.stdout
                    or stderr_marker not in result.stderr):
                raise AssertionError(f"{name}: unexpected result: {result!r}")
            if name == "missing-folder" and "Diagnostic:" not in result.stderr:
                raise AssertionError("missing folder has no diagnostic")
            runs.append({"case": name, "exit_code": result.returncode,
                         "groups": 0, "stderr": result.stderr})
        if list(empty.iterdir()) or missing.exists():
            raise AssertionError("scan created files or a missing root")
        healthy_root = root / "d0"
        healthy_partition = []
        for paths in expected.values():
            retained = {path for path in paths if Path(path).parent == healthy_root}
            if len(retained) > 1:
                healthy_partition.append(frozenset(retained))
        assert healthy_partition, "mixed-root control needs known duplicates"
        for name, roots in (("missing-first", [missing, healthy_root]),
                            ("missing-last", [healthy_root, missing])):
            result = subprocess.run([str(binary), *map(str, roots)], cwd=root,
                                    capture_output=True, text=True, timeout=60)
            if (result.returncode != 1 or "Scan incomplete:" not in result.stderr
                    or "Diagnostic:" not in result.stderr
                    or parse_groups(result.stdout) != set(healthy_partition)):
                raise AssertionError(f"{name}: healthy results lost: {result!r}")
            runs.append({"case": name, "exit_code": result.returncode,
                         "groups": len(healthy_partition), "stderr": result.stderr})
        if before != {str(path): file_state(Path(path)) for path in before}:
            raise AssertionError("boundary scans changed original fixture state")
        if args.large_mib:
            large = root / "large-middle-edit"
            large.mkdir()
            paths = [large / name for name in ("original.bin", "copy.bin", "different.bin")]
            size = args.large_mib * 1024 * 1024
            block = bytes(range(256)) * 4096
            for path in paths:
                with path.open("wb") as output:
                    if args.dense_large:
                        for _ in range(args.large_mib):
                            output.write(block)
                    else:
                        output.truncate(size)
                    output.seek(0)
                    output.write(b"equal leading bytes")
                    output.seek(size - 20)
                    output.write(b"equal trailing bytes")
            with paths[2].open("r+b") as output:
                output.seek(size // 2)
                output.write(b"middle edit")
            if not same_bytes(paths[0], paths[1]) or same_bytes(paths[0], paths[2]):
                raise AssertionError("large fixture byte oracle failed")
            initial = {str(path): file_state(path) for path in paths}
            result = subprocess.run([str(binary), str(large)], capture_output=True,
                                    text=True, timeout=60)
            if (result.returncode != 0
                    or parse_groups(result.stdout) != {frozenset(map(str, paths[:2]))}):
                raise AssertionError(f"large middle edit: wrong partition: {result!r}")
            if initial != {str(path): file_state(path) for path in paths}:
                raise AssertionError("large scan changed fixture state")
            runs.append({"case": "large-middle-edit", "bytes_per_file": size,
                         "storage_fixture": "dense-written" if args.dense_large else "sparse",
                         "files": 3, "groups": 1, "exit_code": result.returncode,
                         "stderr": result.stderr})
        if os.name == "posix":
            links = root / "physical-aliases"
            links.mkdir()
            original, alias, copy = [links / name for name in
                                     ("original.bin", "hardlink.bin", "copy.bin")]
            payload = b"physical identity differs from byte equality\0"
            original.write_bytes(payload)
            os.link(original, alias)
            copy.write_bytes(payload)
            (links / "symbolic.bin").symlink_to(original)
            (links / "cycle").symlink_to(links, target_is_directory=True)
            alias_prefix = "Same physical file (aliases, not separate copies): "
            result = subprocess.run([str(binary), str(links)], capture_output=True,
                                    text=True, timeout=60)
            alias_lines = [line for line in result.stdout.splitlines()
                           if line.startswith(alias_prefix)]
            group_output = "\n".join(line for line in result.stdout.splitlines()
                                     if not line.startswith(alias_prefix))
            groups = parse_groups(group_output)
            physical_paths = {str(original), str(alias)}
            if (result.returncode != 0 or len(alias_lines) != 1
                    or set(json.loads(alias_lines[0][len(alias_prefix):])) != physical_paths
                    or len(groups) != 1):
                raise AssertionError(f"physical aliases: incorrect report: {result!r}")
            group = next(iter(groups))
            if (len(group) != 2 or str(copy) not in group
                    or len(group & physical_paths) != 1
                    or result.stderr.count("SymlinkSkipped") != 2
                    or "Scan complete: 2 files observed" not in result.stderr):
                raise AssertionError(f"physical aliases: copies or links miscounted: {result!r}")
            if any(path.read_bytes() != payload for path in (original, alias, copy)):
                raise AssertionError("physical alias scan changed fixture contents")
            if not original.samefile(alias) or original.samefile(copy):
                raise AssertionError("physical alias fixture identity changed")
            runs.append({"case": "physical-aliases-and-symlink-cycle",
                         "exit_code": result.returncode, "groups": 1,
                         "alias_groups": 1, "stderr": result.stderr})
            special = root / "special-files"
            special.mkdir()
            fifo = special / "unconnected.fifo"
            os.mkfifo(fifo)
            payload = b"healthy files beside an unopened FIFO"
            paths = [special / "first.bin", special / "second.bin"]
            for path in paths:
                path.write_bytes(payload)
            for name, scan_root, expected_groups in (
                    ("fifo-with-healthy-files", special,
                     {frozenset(map(str, paths))}),
                    ("fifo-as-root", fifo, set())):
                # No writer connects: opening this FIFO for a blocking read
                # would hang. The subprocess timeout makes that a test failure.
                result = subprocess.run([str(binary), str(scan_root)],
                                        capture_output=True, text=True, timeout=5)
                if (result.returncode != 0
                        or parse_groups(result.stdout) != expected_groups
                        or result.stderr.count("NotRegular") != 1
                        or "Scan complete:" not in result.stderr):
                    raise AssertionError(f"{name}: incorrect report: {result!r}")
                runs.append({"case": name, "exit_code": result.returncode,
                             "groups": len(expected_groups), "stderr": result.stderr})
            if any(path.read_bytes() != payload for path in paths):
                raise AssertionError("FIFO scan changed healthy fixture contents")
        else:
            runs.append({"case": "physical-aliases-and-symlink-cycle",
                         "skipped": "POSIX link fixture only"})
            runs.append({"case": "fifo-fixtures", "skipped": "POSIX FIFO fixture only"})
    if digest(binary) != binary_hash:
        raise AssertionError("binary changed during qualification")
    report = {"seed": args.seed, "binary_sha256": binary_hash,
              "files": len(before), "expected_groups": len(oracle), "runs": runs,
              "literal_option_folder_files": 6,
              "base_fixture_preserved_fields": ["sha256", "device", "inode", "size",
                                                "mtime_ns", "mode", "links"],
              "scope": "Generated local byte oracle; not concurrent mutation, visual, or all-platform coverage"}
    if args.report:
        with args.report.open("x", encoding="utf-8") as output:
            json.dump(report, output, indent=2)
            output.write("\n")
    print(json.dumps(report, indent=2))


if __name__ == "__main__":
    main()
